import{_ as t,o as l,c as a,a3 as s}from"./chunks/framework.CDCjIvJ8.js";const u=JSON.parse('{"title":"Row-level security","description":"","frontmatter":{},"headers":[],"relativePath":"security/row-level-security.md","filePath":"security/row-level-security.md","lastUpdated":1789296458000}'),i={name:"security/row-level-security.md"};function n(d,e,o,r,c,h){return l(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="row-level-security" tabindex="-1">Row-level security <a class="header-anchor" href="#row-level-security" aria-label="Permalink to &quot;Row-level security&quot;">​</a></h1><p>Migration 005 enables RLS on all 23 tables and defines policies for each.</p><h2 id="why-it-was-needed" tabindex="-1">Why it was needed <a class="header-anchor" href="#why-it-was-needed" aria-label="Permalink to &quot;Why it was needed&quot;">​</a></h2><p>Migrations 001–004 created twenty-three tables and enabled RLS on <strong>none</strong> of them. Authorization existed only in application code, so any path reaching the database with a user-scoped key — a leaked anon key, a direct PostgREST call, a future endpoint that forgets its check — had unrestricted access to every row.</p><h2 id="current-honest-status" tabindex="-1">Current honest status <a class="header-anchor" href="#current-honest-status" aria-label="Permalink to &quot;Current honest status&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Read this before relying on RLS</p><p>The backend still connects with the <strong>service-role key</strong>, which is <code>BYPASSRLS</code> by design. Today these policies defend against:</p><ul><li>a leaked or misused anon key,</li><li>direct PostgREST access,</li><li>anything using <code>get_user_scoped_client()</code>.</li></ul><p>They are <strong>not yet</strong> the enforcement boundary for the API&#39;s own queries. Migrating the repositories onto request-scoped clients is the remaining work; <code>get_user_scoped_client()</code> exists for it. Until then, the application-layer ownership checks are the primary control and RLS is the backstop for everything else.</p></div><h2 id="helper-functions" tabindex="-1">Helper functions <a class="header-anchor" href="#helper-functions" aria-label="Permalink to &quot;Helper functions&quot;">​</a></h2><p><code>SECURITY DEFINER</code>, because reading a role from <code>profiles</code> must not itself pass through the <code>profiles</code> policies — without that, every policy calling these would recurse.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Returns</th></tr></thead><tbody><tr><td style="text-align:left;"><code>current_user_role()</code></td><td style="text-align:left;">The caller&#39;s role, or null if inactive</td></tr><tr><td style="text-align:left;"><code>is_teacher()</code> / <code>is_admin()</code></td><td style="text-align:left;">Role predicates</td></tr><tr><td style="text-align:left;"><code>owns_draft_version(uuid)</code></td><td style="text-align:left;">Walks <code>draft_versions → drafts.user_id</code></td></tr><tr><td style="text-align:left;"><code>teaches_evaluation(uuid)</code></td><td style="text-align:left;">Whether the caller&#39;s assignment received it</td></tr><tr><td style="text-align:left;"><code>teaches_class(uuid)</code></td><td style="text-align:left;">Class ownership</td></tr><tr><td style="text-align:left;"><code>is_enrolled_in(uuid)</code></td><td style="text-align:left;">Active enrollment</td></tr><tr><td style="text-align:left;"><code>shares_class_with(uuid)</code></td><td style="text-align:left;">Classmate test, for scoped leaderboards</td></tr></tbody></table><h2 id="policy-summary" tabindex="-1">Policy summary <a class="header-anchor" href="#policy-summary" aria-label="Permalink to &quot;Policy summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Table</th><th style="text-align:left;">Student</th><th style="text-align:left;">Teacher</th></tr></thead><tbody><tr><td style="text-align:left;"><code>profiles</code></td><td style="text-align:left;">Own row</td><td style="text-align:left;">Read all</td></tr><tr><td style="text-align:left;"><code>drafts</code></td><td style="text-align:left;">Full on own</td><td style="text-align:left;">Read once submitted to their assignment</td></tr><tr><td style="text-align:left;"><code>draft_versions</code></td><td style="text-align:left;">Full via parent draft</td><td style="text-align:left;">Read once submitted to theirs</td></tr><tr><td style="text-align:left;"><code>evaluations</code></td><td style="text-align:left;">Read own</td><td style="text-align:left;">Read + override on their coursework only</td></tr><tr><td style="text-align:left;"><code>evaluation_evidence</code></td><td style="text-align:left;">Read own</td><td style="text-align:left;">Read on their coursework</td></tr><tr><td style="text-align:left;"><code>conversations</code> / <code>messages</code></td><td style="text-align:left;">Full on own</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>roadmaps</code> / <code>roadmap_items</code></td><td style="text-align:left;">Full on own</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>student_skills</code></td><td style="text-align:left;">Read own</td><td style="text-align:left;">Read all</td></tr><tr><td style="text-align:left;"><code>classes</code></td><td style="text-align:left;">Read if enrolled</td><td style="text-align:left;">Full on own</td></tr><tr><td style="text-align:left;"><code>class_enrollments</code></td><td style="text-align:left;">Read own row only</td><td style="text-align:left;">Full on own classes</td></tr><tr><td style="text-align:left;"><code>invitations</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Read on own classes</td></tr><tr><td style="text-align:left;"><code>assignments</code></td><td style="text-align:left;">Read published in their classes</td><td style="text-align:left;">Full on own</td></tr><tr><td style="text-align:left;"><code>submissions</code></td><td style="text-align:left;">Read own, insert own</td><td style="text-align:left;">Full via own assignments</td></tr><tr><td style="text-align:left;"><code>audit_log</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Admin read only</td></tr></tbody></table><p><code>faculty_registration_codes</code> and <code>email_outbox</code> carry <strong>no policies at all</strong>. With RLS enabled and nothing granted, they are reachable only by the service role. Both hold credential-equivalent or personal data.</p><h2 id="force-row-level-security" tabindex="-1"><code>FORCE ROW LEVEL SECURITY</code> <a class="header-anchor" href="#force-row-level-security" aria-label="Permalink to &quot;`FORCE ROW LEVEL SECURITY`&quot;">​</a></h2><p>Applied to every table alongside <code>ENABLE</code>. <code>ENABLE</code> alone exempts the table owner, so a connection that happened to be owner-privileged would silently bypass every policy.</p><h2 id="column-level-grants" tabindex="-1">Column-level grants <a class="header-anchor" href="#column-level-grants" aria-label="Permalink to &quot;Column-level grants&quot;">​</a></h2><p>RLS gates rows, not columns. A student permitted to read a quiz question would also read its <code>correct_option</code>, and likewise <code>exercises.model_solution</code>.</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REVOKE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">quiz_questions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> authenticated, anon;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (id, quiz_id, question_text, options, order_index)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">quiz_questions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> authenticated;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>correct_option</code> and <code>explanation</code> are both omitted — each discloses the answer before the attempt is graded. The service role, which grades the attempt, still reads them.</p><h2 id="_404-not-403" tabindex="-1">404, not 403 <a class="header-anchor" href="#_404-not-403" aria-label="Permalink to &quot;404, not 403&quot;">​</a></h2><p>Policies that deny a read make the row simply not exist for that caller, which naturally produces a 404. The application deliberately matches this: returning 403 would confirm the row exists and turn the endpoint into an id oracle.</p><h2 id="testing-policies" tabindex="-1">Testing policies <a class="header-anchor" href="#testing-policies" aria-label="Permalink to &quot;Testing policies&quot;">​</a></h2><p>Policies are not exercised by the current test suite, because doing so requires a real Supabase project with <code>auth.uid()</code>. CI verifies structure instead:</p><ul><li>every migration applies cleanly in order,</li><li>no public table lacks RLS.</li></ul><p>Behavioural policy tests against a disposable Supabase project are the gap.</p>',24)])])}const y=t(i,[["render",n]]);export{u as __pageData,y as default};
